(function(){
  'use strict';
  const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function overview(c){const {E,state,operation:o,heading,button,map,number}=c,active=state.plan&&!state.plan.completed;
    return heading('ALMACÉN GUARDADO · '+window.KbitLayout.presets.find(p=>p.id===o.config.geometry).name,esc(o.config.name),'Tu diseño, tus ubicaciones y una misma secuencia para la animación y las tareas.',button('Editar diseño','design','warehouse')+button('Simular movimientos','visual-demo','spark')+button(active?'Continuar tareas':'Preparar turno',active?'tasks':'plan','arrow','btn btn-primary'))+
    '<div class="notice"><span>'+E.products.length+' productos de demostración colocados en tu diseño. Los pedidos son de ejemplo; las direcciones y los sectores pertenecen a este almacén.</span></div><div class="content-grid"><div>'+map()+'<div class="visual-top-stats"><span><b>'+E.products.length+'</b> productos de ejemplo</span><span><b>'+number(o.stats.locations)+'</b> ubicaciones del almacén</span><span><b>'+o.sectors.length+'</b> sectores</span></div></div><aside class="side-stack"><section class="next-action"><div class="eyebrow">UNA MISMA OPERACIÓN</div><h2>Del movimiento<br>a la tarea.</h2><p>Reproduce el plan, revisa el sector y confirma cada movimiento cuando se haya realizado.</p>'+button('Simular movimientos','visual-demo','arrow','btn btn-primary btn-full')+button('Ver tareas','tasks','checklist','btn btn-full')+'</section>'+dataPanel(c)+'<section class="panel details-panel"><h3>Cómo se ejecuta</h3><p class="small muted">Las tareas se presentan en bloques por sector. Los traslados indican origen y destino; el orden mantiene cada destino libre. La simulación no confirma tareas.</p></section></aside></div>';
  }
  function dataPanel({E,state,operation:o,number}){return '<section class="panel details-panel"><h3>'+esc(o.config.name)+'</h3><div class="detail-row"><span>Diseño</span><strong>'+window.KbitLayout.presets.find(p=>p.id===o.config.geometry).name+'</strong></div><div class="detail-row"><span>Capacidad del edificio</span><strong>'+number(o.stats.locations)+' ubicaciones</strong></div><div class="detail-row"><span>Catálogo de ejemplo</span><strong>'+E.products.length+' SKUs</strong></div><div class="detail-row"><span>Reserva temporal</span><strong>'+esc(E.slotName(E.layout.reserved[0]))+'</strong></div><div class="file-chip"><div>'+esc(state.source)+'<small>'+state.orders.length+' pedidos · guardado en este navegador</small></div></div></section>';}
  function flat(c,assignment,highlight=[],tabs=false){const {E,state,operation:o,button}=c,stats=o.stats;
    let svg=window.KbitDesigner.plan(o.config,null,null).replace(/ data-design-(rack|sector)="[^"]*"/g,'').replace(/role="button" tabindex="0"/g,'role="presentation"');
    const radius=Math.max(stats.width,stats.depth)/125,occupied=new Map(assignment.map((slot,id)=>[slot,id]));
    const points=o.slots.map((s,i)=>{const id=occupied.get(i);if(id===undefined&&!E.layout.reserved.includes(i))return '';return '<g role="button" tabindex="0" data-action="slot" data-slot="'+i+'" aria-label="'+esc((id===undefined?'Reserva temporal':E.products[id].name)+' · '+s.sector+' · '+s.name)+'"><circle cx="'+(s.x+stats.width/2)+'" cy="'+(s.z+stats.depth/2)+'" r="'+radius+'" fill="'+(id===undefined?'var(--panel)':'var(--fam-'+E.products[id].family+')')+'" stroke="'+(highlight.includes(id)?'var(--accent)':'var(--ink)')+'" stroke-width="'+radius*.25+'"/><title>'+esc(s.sector+' · '+s.name)+'</title></g>';}).join('');svg=svg.replace('</svg>',points+'</svg>');
    return '<section class="panel"><div class="panel-head"><div><h2>'+esc(o.config.name)+' · Plano de productos</h2><p>Las direcciones incluyen sector, pasillo, estante, nivel y hueco.</p></div>'+(tabs?'<div class="map-tabs"><button data-action="map-actual" class="'+(c.mapMode==='actual'?'active':'')+'">Actual</button><button data-action="map-propuesta" class="'+(c.mapMode==='propuesta'?'active':'')+'">Propuesta</button></div>':'')+'</div><div class="operation-flat">'+svg+'</div><div class="operation-location-list">'+E.products.map(p=>{const s=o.slots[assignment[p.id]];return '<button class="operation-location '+(highlight.includes(p.id)?'changed':'')+'" data-action="slot" data-slot="'+assignment[p.id]+'"><span>'+esc(p.name)+'</span><small>'+s.sector+' · '+s.name+'</small></button>';}).join('')+'</div></section>';
  }
  function tasks(c){const {E,state,operation:o,heading,button,map}=c,p=state.plan;
    if(!p?.tasks.length)return heading('TAREAS DEL ALMACÉN',esc(o.config.name),'Genera un plan para ver sus movimientos en este mismo espacio.',button('Preparar turno','plan','arrow','btn btn-primary'))+map();
    const next=p.tasks.find(t=>!t.done),done=p.tasks.filter(t=>t.done).length,progress=Math.round(done/p.tasks.length*100),blocks=o.blocks(p.tasks);
    const groups=blocks.map((block,i)=>'<section class="panel operation-task-block" id="operation-block-'+i+'"><div class="panel-head"><div><div class="eyebrow">BLOQUE '+(i+1)+' · '+(block.tasks.every(t=>t.done)?'COMPLETADO':block.tasks.includes(next)?'EN CURSO':'PENDIENTE')+'</div><h2>Sector '+block.sector+'</h2><p>'+block.tasks.filter(t=>t.done).length+' / '+block.tasks.length+' movimientos confirmados</p></div><span class="pill">'+block.sector+'</span></div>'+block.tasks.map(t=>{const a=o.slots[t.from],b=o.slots[t.to];return '<article class="task '+(t.done?'done':'')+'"><span class="task-index">'+(t.done?'✓':t.id)+'</span><div><h3>'+esc(E.products[t.product].name)+'</h3><p>'+E.products[t.product].code+(t.temporary?' · Reserva temporal':'')+'</p><div class="operation-task-address"><b>'+a.sector+' · '+a.name+'</b><span>→</span><b>'+b.sector+' · '+b.name+'</b></div>'+(a.sector!==b.sector?'<span class="pill">Traslado entre sectores</span>':'')+'</div>'+(t.done?'<span class="pill">Confirmado</span>':t===next?button('Confirmar movimiento','confirm-task','check','btn btn-primary','data-task="'+t.id+'"'):'<span class="task-future">Espera el paso anterior</span>')+'</article>';}).join('')+'</section>').join('');
    return heading('EJECUCIÓN · '+esc(o.config.name),p.completed?'Todo en su ubicación.':'Sector a sector, en orden.','La animación y las tareas usan el mismo plan. Confirma cada movimiento después de realizarlo.',button('Simular plan','visual-demo','spark')+button('Descargar tareas','export','download'))+'<div class="task-scene operation-task-scene">'+map(state.assignment,next?[next.product]:[])+'</div><div class="content-grid"><div class="operation-task-groups">'+groups+'</div><aside class="side-stack"><section class="next-action"><div class="eyebrow">'+(next?'SECTOR ACTUAL':'TURNO COMPLETADO')+'</div><h2>'+(next?o.slots[next.from].sector:'100 %')+'</h2><p>'+done+' de '+p.tasks.length+' movimientos confirmados. La simulación muestra el plan; solo confirmar actualiza las ubicaciones guardadas.</p><div class="progress-track" role="progressbar" aria-label="Movimientos completados" aria-valuenow="'+progress+'" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:'+progress+'%"></div></div>'+button('Ver mi almacén','warehouse','warehouse','btn btn-full')+'</section>'+dataPanel(c)+'<p class="quiet-note">Los bloques siguen las dependencias del plan. Un sector puede volver a aparecer si un destino debe liberarse primero.</p></aside></div>';
  }
  window.KbitOperationUI={overview,tasks,flat,dataPanel};
})();
